	/**
	 * This is called once on initialisation and then once each time the wizard gains new trades (the particle thingy).
	 */
	private void addRandomRecipes(int numberOfItemsToAdd){

		MerchantRecipeList merchantrecipelist;
		merchantrecipelist = new MerchantRecipeList();

		for(int i = 0; i < numberOfItemsToAdd; i++){

			ItemStack itemToSell = ItemStack.EMPTY;

			boolean itemAlreadySold = true;

			Tier tier = Tier.NOVICE;

			while(itemAlreadySold){

				itemAlreadySold = false;

				/* New way of getting random item, by giving a chance to increase the tier which depends on how much the
				 * player has already traded with the wizard. The more the player has traded with the wizard, the more
				 * likely they are to get items of a higher tier. The -4 is to ignore the original 4 trades. For
				 * reference, the chances are as follows: Trades done Basic Apprentice Advanced Master 0 50% 25% 18% 8%
				 * 1 46% 25% 20% 9% 2 42% 24% 22% 12% 3 38% 24% 24% 14% 4 34% 22% 26% 17% 5 30% 21% 28% 21% 6 26% 19%
				 * 30% 24% 7 22% 17% 32% 28% 8 18% 15% 34% 33% */

				double tierIncreaseChance = 0.5 + 0.04 * (Math.max(this.trades.size() - 4, 0));

				tier = Tier.NOVICE;

				if(rand.nextDouble() < tierIncreaseChance){
					tier = Tier.APPRENTICE;
					if(rand.nextDouble() < tierIncreaseChance){
						tier = Tier.ADVANCED;
						if(rand.nextDouble() < tierIncreaseChance * 0.6){
							tier = Tier.MASTER;
						}
					}
				}

				itemToSell = this.getRandomItemOfTier(tier);

				for(Object recipe : merchantrecipelist){
					if(ItemStack.areItemStacksEqual(((MerchantRecipe)recipe).getItemToSell(), itemToSell))
						itemAlreadySold = true;
				}

				if(this.trades != null){
					for(Object recipe : this.trades){
						if(ItemStack.areItemStacksEqual(((MerchantRecipe)recipe).getItemToSell(), itemToSell))
							itemAlreadySold = true;
					}
				}
			}

			// Don't know how it can ever be empty here, but it's a failsafe.
			if(itemToSell.isEmpty()) return;

			ItemStack secondItemToBuy = tier == Tier.MASTER ? new ItemStack(WizardryItems.astral_diamond)
					: new ItemStack(WizardryItems.magic_crystal, tier.ordinal() * 3 + 1 + rand.nextInt(4));

			merchantrecipelist.add(new MerchantRecipe(this.getRandomPrice(tier), secondItemToBuy, itemToSell));
		}

		Collections.shuffle(merchantrecipelist);

		if(this.trades == null){
			this.trades = new WildcardTradeList();
		}

		this.trades.addAll(merchantrecipelist);
	}

	// TODO: Switch all of this over to some kind of loot pool system?

	@SuppressWarnings("unchecked")
	private ItemStack getRandomPrice(Tier tier){

		Map<Pair<ResourceLocation, Short>, Integer> map = Wizardry.settings.currencyItems;
		// This isn't that efficient but it's not called very often really so it doesn't matter
		Pair<ResourceLocation, Short> itemName = map.keySet().toArray(new Pair[0])[rand.nextInt(map.size())];
		Item item = Item.REGISTRY.getObject(itemName.getLeft());
		short meta = itemName.getRight();
		int value;

		if(item == null){
			Wizardry.logger.warn("Invalid item in currency items: {}", itemName);
			item = Items.EMERALD; // Fallback item
			value = 6;
		}else{
			value = map.get(itemName);
		}

		// ((tier.ordinal() + 1) * 16 + rand.nextInt(6)) gives a 'value' for the item being bought
		// This is then divided by the value of the currency item to give a price
		// The absolute maximum stack size that can result from this calculation (with value = 1) is 64.
		ItemStack result = new ItemStack(item, MathHelper.clamp((8 + tier.ordinal() * 16 + rand.nextInt(9)) / value, 1, 64), meta);
		NBTTagCompound nbt = Wizardry.settings.currencyItemNbt.get(itemName);
		if(nbt != null) result.setTagCompound(nbt.copy());
		return result;
	}

	private ItemStack getRandomItemOfTier(Tier tier){

		int randomiser;

		// All enabled spells of the given tier
		List<Spell> spells = Spell.getSpells(new Spell.TierElementFilter(tier, null, SpellProperties.Context.TRADES));
		// All enabled spells of the given tier that match this wizard's element
		List<Spell> specialismSpells = Spell.getSpells(new Spell.TierElementFilter(tier, this.getElement(), SpellProperties.Context.TRADES));

		// Wizards don't sell scrolls
		spells.removeIf(s -> !s.isEnabled(SpellProperties.Context.BOOK));
		specialismSpells.removeIf(s -> !s.isEnabled(SpellProperties.Context.BOOK));

		// This code is sooooooo much neater with the new filter system!
		switch(tier){

		case NOVICE:
			randomiser = rand.nextInt(5);
			if(randomiser < 4 && !spells.isEmpty()){
				if(this.getElement() != Element.MAGIC && rand.nextInt(4) > 0 && !specialismSpells.isEmpty()){
					// This means it is more likely for spell books sold to be of the same element as the wizard if the
					// wizard has an element.
					return getBookStackForSpell(specialismSpells.get(rand.nextInt(specialismSpells.size())));
				}else{
					return getBookStackForSpell(spells.get(rand.nextInt(spells.size())));
				}
			}else{
				if(this.getElement() != Element.MAGIC && rand.nextInt(4) > 0){
					// This means it is more likely for wands sold to be of the same element as the wizard if the wizard
					// has an element.
					return new ItemStack(WizardryItems.getWand(tier, this.getElement()));
				}else{
					return new ItemStack(
							WizardryItems.getWand(tier, Element.values()[rand.nextInt(Element.values().length)]));
				}
			}

		case APPRENTICE:
			randomiser = rand.nextInt(Wizardry.settings.discoveryMode ? 12 : 10);
			if(randomiser < 5 && !spells.isEmpty()){
				if(this.getElement() != Element.MAGIC && rand.nextInt(4) > 0 && !specialismSpells.isEmpty()){
					// This means it is more likely for spell books sold to be of the same element as the wizard if the
					// wizard has an element.
					return getBookStackForSpell(specialismSpells.get(rand.nextInt(specialismSpells.size())));
				}else{
					return getBookStackForSpell(spells.get(rand.nextInt(spells.size())));
				}
			}else if(randomiser < 6){
				if(this.getElement() != Element.MAGIC && rand.nextInt(4) > 0){
					// This means it is more likely for wands sold to be of the same element as the wizard if the wizard
					// has an element.
					return new ItemStack(WizardryItems.getWand(tier, this.getElement()));
				}else{
					return new ItemStack(
							WizardryItems.getWand(tier, Element.values()[rand.nextInt(Element.values().length)]));
				}
			}else if(randomiser < 8){
				return new ItemStack(WizardryItems.arcane_tome, 1, 1);
			}else if(randomiser < 10){
				EntityEquipmentSlot slot = InventoryUtils.ARMOUR_SLOTS[rand.nextInt(InventoryUtils.ARMOUR_SLOTS.length)];
				if(this.getElement() != Element.MAGIC && rand.nextInt(4) > 0){
					// This means it is more likely for armour sold to be of the same element as the wizard if the
					// wizard has an element.
					return new ItemStack(WizardryItems.getArmour(this.getElement(), slot));
				}else{
					return new ItemStack(
							WizardryItems.getArmour(Element.values()[rand.nextInt(Element.values().length)], slot));
				}
			}else{
				// Don't need to check for discovery mode here since it is done above
				return new ItemStack(WizardryItems.identification_scroll);
			}

		case ADVANCED:
			randomiser = rand.nextInt(12);
			if(randomiser < 5 && !spells.isEmpty()){
				if(this.getElement() != Element.MAGIC && rand.nextInt(4) > 0 && !specialismSpells.isEmpty()){
					// This means it is more likely for spell books sold to be of the same element as the wizard if the
					// wizard has an element.
					return getBookStackForSpell(specialismSpells.get(rand.nextInt(specialismSpells.size())));
				}else{
					return getBookStackForSpell(spells.get(rand.nextInt(spells.size())));
				}
			}else if(randomiser < 6){
				if(this.getElement() != Element.MAGIC && rand.nextInt(4) > 0){
					// This means it is more likely for wands sold to be of the same element as the wizard if the wizard
					// has an element.
					return new ItemStack(WizardryItems.getWand(tier, this.getElement()));
				}else{
					return new ItemStack(
							WizardryItems.getWand(tier, Element.values()[rand.nextInt(Element.values().length)]));
				}
			}else if(randomiser < 8){
				return new ItemStack(WizardryItems.arcane_tome, 1, 2);
			}else{
				List<Item> upgrades = new ArrayList<Item>(WandHelper.getSpecialUpgrades());
				randomiser = rand.nextInt(upgrades.size());
				return new ItemStack(upgrades.get(randomiser));
			}

		case MASTER:
			// If a regular wizard rolls a master trade, it can only be a simple master wand or a tome of arcana
			randomiser = this.getElement() != Element.MAGIC ? rand.nextInt(8) : 5 + rand.nextInt(3);

			if(randomiser < 5 && this.getElement() != Element.MAGIC && !specialismSpells.isEmpty()){
				// Master spells can only be sold by a specialist in that element.
				return getBookStackForSpell(specialismSpells.get(rand.nextInt(specialismSpells.size())));

			}else if(randomiser < 6){
				if(this.getElement() != Element.MAGIC && rand.nextInt(4) > 0){
					// Master elemental wands can only be sold by a specialist in that element.
					return new ItemStack(WizardryItems.getWand(tier, this.getElement()));
				}else{
					return new ItemStack(WizardryItems.master_wand);
				}
			}else{
				return new ItemStack(WizardryItems.arcane_tome, 1, 3);
			}
		}

		return new ItemStack(Blocks.STONE);
	}

	@Override
	public IEntityLivingData onInitialSpawn(DifficultyInstance difficulty, IEntityLivingData livingdata){

		livingdata = super.onInitialSpawn(difficulty, livingdata);

		textureIndex = this.rand.nextInt(6);

		if(rand.nextBoolean()){
			this.setElement(Element.values()[rand.nextInt(Element.values().length - 1) + 1]);
		}else{
			this.setElement(Element.MAGIC);
		}

		Element element = this.getElement();

		// Adds armour.
		for(EntityEquipmentSlot slot : InventoryUtils.ARMOUR_SLOTS){
			this.setItemStackToSlot(slot, new ItemStack(WizardryItems.getArmour(element, slot)));
		}

		// Default chance is 0.085f, for reference.
		for(EntityEquipmentSlot slot : EntityEquipmentSlot.values())
			this.setDropChance(slot, 0.0f);

		// All wizards know magic missile, even if it is disabled.
		spells.add(Spells.magic_missile);

		Tier maxTier = populateSpells(this, spells, element, false, 3, rand);

		// Now done after the spells so it can take the tier into account.
		ItemStack wand = new ItemStack(WizardryItems.getWand(maxTier, element));
		ArrayList<Spell> list = new ArrayList<>(spells);
		list.add(Spells.heal);
		WandHelper.setSpells(wand, list.toArray(new Spell[5]));
		this.setItemStackToSlot(EntityEquipmentSlot.MAINHAND, wand);

		this.setHealCooldown(50);

		return livingdata;
	}

	/**
	 * Adds n random spells to the given list. The spells will be of the given element if possible. Extracted as a
	 * separate function since it was the same in both EntityWizard and EntityEvilWizard.
	 *
	 * @param wizard The wizard whose spells are to be populated.
	 * @param spells The spell list to be populated.
	 * @param e The element that the spells should belong to, or {@link Element#MAGIC} for a random element each time.
	 * @param master Whether to include master spells.
	 * @param n The number of spells to add.
	 * @param random A random number generator to use.
	 * @return The tier of the highest-tier spell that was added to the list.
	 */
	static Tier populateSpells(final EntityLiving wizard, List<Spell> spells, Element e, boolean master, int n, Random random){

		// This is the tier of the highest tier spell added.
		Tier maxTier = Tier.NOVICE;

		List<Spell> npcSpells = Spell.getSpells(s -> s.canBeCastBy(wizard, false));

		for(int i = 0; i < n; i++){

			Tier tier;
			// If the wizard has no element, it picks a random one each time.
			Element element = e == Element.MAGIC ? Element.values()[random.nextInt(Element.values().length)] : e;

			int randomiser = random.nextInt(20);

			// Uses its own special weighting
			if(randomiser < 10){
				tier = Tier.NOVICE;
			}else if(randomiser < 16){
				tier = Tier.APPRENTICE;
			}else if(randomiser < 19 || !master){
				tier = Tier.ADVANCED;
			}else{
				tier = Tier.MASTER;
			}

			if(tier.ordinal() > maxTier.ordinal()) maxTier = tier;

			// Finds all the spells of the chosen tier and element
			List<Spell> list = Spell.getSpells(new Spell.TierElementFilter(tier, element, SpellProperties.Context.NPCS));
			// Keeps only spells which can be cast by NPCs
			list.retainAll(npcSpells);
			// Removes spells that the wizard already has
			list.removeAll(spells);

			// Ensures the tier chosen actually has spells in it. (isEmpty() is exactly the same as size() == 0)
			if(list.isEmpty()){
				// If there are no spells applicable, tier and element restrictions are removed to give maximum
				// possibility of there being an applicable spell.
				list = npcSpells;
				// Removes spells that the wizard already has
				list.removeAll(spells);
			}

			// If the list is still empty now, there must be less than 3 enabled spells that can be cast by wizards
			// (excluding magic missile). In this case, having empty slots seems reasonable.
			if(!list.isEmpty()) spells.add(list.get(random.nextInt(list.size())));

		}

		return maxTier;
	}

	/**
	 * Helper method to handle addon spell books.
	 * @param spell the spell to look up.
	 * @return Checks all items of the spell's namespace (modid) if they are applicable for the spell and returns the first match, or falls back to WizardryItems.spell_book if no match was found.
	 */
	public static ItemStack getBookStackForSpell(Spell spell) {
		String modid = spell.getRegistryName().getNamespace();
		if (modid.equals(Wizardry.MODID)) {
			return new ItemStack(WizardryItems.spell_book, 1, spell.metadata());
		}
		Optional<Item> firstMatch = ForgeRegistries.ITEMS.getValuesCollection().stream().filter(v -> v instanceof ItemSpellBook && spell.applicableForItem(v)
						&& v.getRegistryName().getNamespace().equals(modid)).findFirst();

		return firstMatch.map(item -> new ItemStack(item, 1, spell.metadata())).orElseGet(() -> new ItemStack(WizardryItems.spell_book, 1, spell.metadata()));
	}

	@Override
	public void writeSpawnData(ByteBuf data){
		data.writeInt(textureIndex);
	}

	@Override
	public void readSpawnData(ByteBuf data){
		textureIndex = data.readInt();
	}

	@Override
	public boolean attackEntityFrom(DamageSource source, float damage){

		if(source.getTrueSource() instanceof EntityPlayer){
			WizardryAdvancementTriggers.anger_wizard.triggerFor((EntityPlayer)source.getTrueSource());
		}

		return super.attackEntityFrom(source, damage);
	}

	/**
	 * Sets the list of blocks that are part of this wizard's tower. If a player breaks any of these blocks, the wizard
	 * will get angry and attack them.
	 * 
	 * @param blocks A Set of BlockPos objects representing the blocks in the tower.
	 */
	public void setTowerBlocks(Set<BlockPos> blocks){
		this.towerBlocks = blocks;
	}

	/** Tests whether the block at the given coordinates is part of this wizard's tower. */
	public boolean isBlockPartOfTower(BlockPos pos){
		if(this.towerBlocks == null) return false;
		// Uses .equals() rather than == so this will work fine.
		return this.towerBlocks.contains(pos);
	}

	@SubscribeEvent
	public static void onBlockBreakEvent(BlockEvent.BreakEvent event){
		// Makes wizards angry if a player breaks a block in their tower
		if(!(event.getPlayer() instanceof FakePlayer)){

			List<EntityWizard> wizards = EntityUtils.getEntitiesWithinRadius(64, event.getPos().getX(),
					event.getPos().getY(), event.getPos().getZ(), event.getWorld(), EntityWizard.class);

			if(!wizards.isEmpty()){
				for(EntityWizard wizard : wizards){
					if(wizard.isBlockPartOfTower(event.getPos())){
						wizard.setRevengeTarget(event.getPlayer());
						WizardryAdvancementTriggers.anger_wizard.triggerFor(event.getPlayer());
					}
				}
			}
		}
	}

	// Copied from their respective AI classes

	public static class EntityAILookAtTradePlayer extends EntityAIWatchClosest {

	    private final EntityWizard wizard;

	    public EntityAILookAtTradePlayer(EntityWizard wizard){
	        super(wizard, EntityPlayer.class, 8.0F);
	        this.wizard = wizard;
	    }

	    @Override
	    public boolean shouldExecute(){
	        if(this.wizard.isTrading()){
	            this.closestEntity = this.wizard.getCustomer();
	            return true;
	        }else{
	            return false;
	        }
	    }
	}

	public static class EntityAITradePlayer extends EntityAIBase {

		private final EntityWizard wizard;

	    public EntityAITradePlayer(EntityWizard wizard){
	        this.wizard = wizard;
	        this.setMutexBits(5);
	    }

	    @Override
	    public boolean shouldExecute(){

	        if(!this.wizard.isEntityAlive()){
	            return false;
	        }else if(this.wizard.isInWater()){
	            return false;
	        }else if(!this.wizard.onGround){
	            return false;
	        }else if(this.wizard.velocityChanged){
	            return false;
	        }else{

	            EntityPlayer entityplayer = this.wizard.getCustomer();

	            if(entityplayer == null){
	                return false;
	            }else if(this.wizard.getDistanceSq(entityplayer) > 16.0D){
	                return false;
	            }else{
	                return entityplayer.openContainer != null;
	            }
	        }
	    }

	    @Override
	    public void startExecuting(){
	        this.wizard.getNavigator().clearPath();
	    }

	    @Override
	    public void resetTask(){
	        this.wizard.setCustomer((EntityPlayer)null);
	    }
	}

}

package electroblob.wizardry.entity.living;

import electroblob.wizardry.Wizardry;
import electroblob.wizardry.item.ItemArtefact;
import electroblob.wizardry.registry.WizardryItems;
import net.minecraft.entity.EntityFlying;
import net.minecraft.entity.EntityLivingBase;
import net.minecraft.entity.ai.EntityAIHurtByTarget;
import net.minecraft.entity.ai.EntityAIMoveThroughVillage;
import net.minecraft.entity.ai.EntityAINearestAttackableTarget;
import net.minecraft.entity.monster.EntityZombie;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.init.Items;
import net.minecraft.inventory.EntityEquipmentSlot;
import net.minecraft.item.Item;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.network.datasync.DataParameter;
import net.minecraft.network.datasync.DataSerializers;
import net.minecraft.network.datasync.EntityDataManager;
import net.minecraft.util.EnumHand;
import net.minecraft.util.EnumParticleTypes;
import net.minecraft.util.ResourceLocation;
import net.minecraft.util.text.ITextComponent;
import net.minecraft.util.text.TextComponentTranslation;
import net.minecraft.world.DifficultyInstance;
import net.minecraft.world.EnumDifficulty;
import net.minecraft.world.World;

import java.util.UUID;

public class EntityZombieMinion extends EntityZombie implements ISummonedCreature {

	private static final DataParameter<Boolean> SPAWN_PARTICLES = EntityDataManager.createKey(EntityZombieMinion.class, DataSerializers.BOOLEAN);

	// Field implementations
	private int lifetime = -1;
	private UUID casterUUID;

	// Setter + getter implementations
	@Override public int getLifetime(){ return lifetime; }
	@Override public void setLifetime(int lifetime){ this.lifetime = lifetime; }
	@Override public UUID getOwnerId(){ return casterUUID; }
	@Override public void setOwnerId(UUID uuid){ this.casterUUID = uuid; }

	/** Creates a new zombie minion in the given world. */
	public EntityZombieMinion(World world){
		super(world);
		this.experienceValue = 0;
	}

	@Override
	protected void entityInit(){
		super.entityInit();
		this.dataManager.register(SPAWN_PARTICLES, true);
	}

	// EntityZombie overrides (EntityZombie is a complex class so there are lots of these)

	@Override
	protected void applyEntityAI(){
		this.tasks.addTask(6, new EntityAIMoveThroughVillage(this, 1.0D, false));
		this.targetTasks.addTask(1, new EntityAIHurtByTarget(this, false));
		this.targetTasks.addTask(2, new EntityAINearestAttackableTarget<>(this, EntityLivingBase.class,
				0, false, true, this.getTargetSelector()));
	}

	@Override public boolean isChild(){ return false; }
	@Override public void setChild(boolean childZombie){} // Can't be a child
	@Override protected void setEquipmentBasedOnDifficulty(DifficultyInstance difficulty){} // They don't have equipment!
	@Override public void onKillEntity(EntityLivingBase entityLivingIn){} // Turns villagers to zombies in EntityZombie
	@Override public void setChildSize(boolean isChild){}
	@Override protected ItemStack getSkullDrop(){ return ItemStack.EMPTY; }

	// Implementations

	@Override
	public void setRevengeTarget(EntityLivingBase entity){
		if(this.shouldRevengeTarget(entity)) super.setRevengeTarget(entity);
	}

	@Override
	public void onUpdate(){
		super.onUpdate();
		this.updateDelegate();
	}

	@Override
	public void onSpawn(){
		if(this.dataManager.get(SPAWN_PARTICLES)) this.spawnParticleEffect();
		if(shouldBurnInDay() && getCaster() instanceof EntityPlayer
				&& ItemArtefact.isArtefactActive((EntityPlayer)getCaster(), WizardryItems.charm_undead_helmets)){
			setItemStackToSlot(EntityEquipmentSlot.HEAD, new ItemStack(Items.LEATHER_HELMET));
		}
	}

	@Override
	public void onDespawn(){
		this.spawnParticleEffect();
	}

	private void spawnParticleEffect(){
		if(this.world.isRemote){
			for(int i = 0; i < 15; i++){
				this.world.spawnParticle(EnumParticleTypes.SMOKE_LARGE, this.posX + this.rand.nextFloat() - 0.5f,
						this.posY + this.rand.nextFloat() * 2, this.posZ + this.rand.nextFloat() - 0.5f, 0, 0, 0);
			}
		}
	}

	@Override
	public boolean hasParticleEffect(){
		return true;
	}

	@Override
	public boolean hasAnimation(){
		return this.dataManager.get(SPAWN_PARTICLES) || this.ticksExisted > 20;
	}

	public void hideParticles(){
		this.dataManager.set(SPAWN_PARTICLES, false);
	}

	@Override
	protected boolean processInteract(EntityPlayer player, EnumHand hand){
		// In this case, the delegate method determines whether super is called.
		// Rather handily, we can make use of Java's short-circuiting method of evaluating OR statements.
		return this.interactDelegate(player, hand) || super.processInteract(player, hand);
	}

	@Override
	public void writeEntityToNBT(NBTTagCompound nbttagcompound){
		super.writeEntityToNBT(nbttagcompound);
		this.writeNBTDelegate(nbttagcompound);
	}

	@Override
	public void readEntityFromNBT(NBTTagCompound nbttagcompound){
		super.readEntityFromNBT(nbttagcompound);
		this.readNBTDelegate(nbttagcompound);
	}

	// Recommended overrides

	@Override protected int getExperiencePoints(EntityPlayer player){ return 0; }
	@Override protected boolean canDropLoot(){ return false; }
	@Override protected Item getDropItem(){ return null; }
	@Override protected ResourceLocation getLootTable(){ return null; }
	@Override public boolean canPickUpLoot(){ return false; }

	// This vanilla method has nothing to do with the custom despawn() method.
	@Override protected boolean canDespawn(){
		return getCaster() == null && getOwnerId() == null;
	}

	@Override
	public boolean getCanSpawnHere(){
		return this.world.getDifficulty() != EnumDifficulty.PEACEFUL;
	}

	@Override
	public boolean canAttackClass(Class<? extends EntityLivingBase> entityType){
		// Returns true unless the given entity type is a flying entity.
		return !EntityFlying.class.isAssignableFrom(entityType);
	}

	@Override
	public ITextComponent getDisplayName(){
		if(getCaster() != null){
			return new TextComponentTranslation(NAMEPLATE_TRANSLATION_KEY, getCaster().getName(),
					new TextComponentTranslation("entity." + this.getEntityString() + ".name"));
		}else{
			return super.getDisplayName();
		}
	}

	@Override
	public boolean hasCustomName(){
		// If this returns true, the renderer will show the nameplate when looking directly at the entity
		return Wizardry.settings.summonedCreatureNames && getCaster() != null;
	}

}

package electroblob.wizardry.entity.living;

import com.google.common.base.Predicate;
import electroblob.wizardry.Wizardry;
import electroblob.wizardry.data.WizardData;
import electroblob.wizardry.integration.DamageSafetyChecker;
import electroblob.wizardry.item.ISpellCastingItem;
import electroblob.wizardry.util.*;
import electroblob.wizardry.util.MagicDamage.DamageType;
import electroblob.wizardry.util.ParticleBuilder.Type;
import io.netty.buffer.ByteBuf;
import net.minecraft.entity.*;
import net.minecraft.entity.monster.IMob;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.util.DamageSource;
import net.minecraft.util.EntityDamageSource;
import net.minecraft.util.EntityDamageSourceIndirect;
import net.minecraft.util.EnumHand;
import net.minecraftforge.event.entity.living.LivingAttackEvent;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.fml.common.eventhandler.EventPriority;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
import net.minecraftforge.fml.common.registry.IEntityAdditionalSpawnData;

import javax.annotation.Nullable;
import java.lang.ref.WeakReference;
import java.util.Arrays;
import java.util.UUID;

/**
 * Interface for all summoned creatures. The code for summoned creatures has been overhauled in Wizardry 2.1, and this
 * interface allows summoned creatures to extend vanilla (or indeed modded) entity classes, so
 * <code>EntitySummonedZombie</code> now extends <code>EntityZombie</code>, for example. This change has two major
 * benefits:
 * <p></p>
 * - There is no longer any need for separate render classes, because summoned creatures are now instances of vanilla
 * types. <i>You don't even need to assign a render class</i> because the supertype should already be assigned the
 * correct one.<br>
 * - Summoned creature classes are now much more robust when it comes to changes between Minecraft versions, since none
 * of the vanilla code needs to be copied.
 * <p></p>
 * <b>Summoned creatures that do not emulate vanilla entities do not directly implement this interface</b>. Instead,
 * they should extend the abstract base implementation, {@link EntitySummonedCreature}.
 * <p></p>
 * All damage dealt by ISummonedCreature instances is redirected via
 * {@link ISummonedCreature#onLivingAttackEvent(LivingAttackEvent)
 * ISummonedCreature.onLivingAttackEvent(LivingAttackEvent)} and replaced by an instance of
 * {@link IElementalDamage IElementalDamage} with the summoner of that creature as the source
 * rather than the creature itself. This means that kills by summoned creatures register as kills for their owner,
 * dropping xp and rare loot if that owner is a player.
 * <p></p>
 * Though this system is a lot better than the previous system, <i>it is not a perfect solution</i>. The old
 * EntitySummonedCreature class overrode some methods from Entity in order to add shared functionality, but this cannot
 * be done with an interface. To get around this problem, this interface contains 5 delegate methods that do the same
 * things, with the aim of centralising as much code as possible, even though it is not automatically applied.
 * <b>Implementing classes must override the corresponding methods from Entity, and within them, call the appropriate
 * delegate method in this interface.</b> It is impossible to enforce this condition, but the summoned creature will not
 * work properly unless it is adhered to. <i>The position of the delegate method call is unimportant, but by convention
 * it is usually at the start of the calling method, which avoids it being unintentionally skipped by a return
 * statement (except for methods where the result of the delegate method should itself be returned).</i>
 * <p></p>
 * It is recommended that when implementing this interface, you begin by copying {@link EntitySummonedCreature} to
 * ensure all the relevant methods are duplicated. You can then change the superclass, override any additional methods
 * and add functionality to any that are already overridden. You will always want to override the AI methods at the very
 * least.
 * <p></p>
 * Due to the limitations of interfaces, some methods that really ought to be protected are public. These are clearly
 * marked as 'Internal, DO NOT CALL'. <b>Don't call them, only implement them.</b>
 * 
 * @since Wizardry 2.1
 * @author Electroblob
 */
/* Quite honestly, this is not what default methods are really for. However, this is modding, and in modding some
 * sacrifices have to be made when it comes to Java style - because adding on to a pre-existing program is not a good
 * way of doing this sort of thing anyway, but we have no choice about that! */
@Mod.EventBusSubscriber
public interface ISummonedCreature extends IEntityAdditionalSpawnData, IEntityOwnable {

	// Remember that ALL fields are static and final in interfaces, even if they don't explicitly state that.
	String NAMEPLATE_TRANSLATION_KEY = "entity." + Wizardry.MODID + ":summonedcreature.nameplate";

	// Setters and getters. The subclass fields that these access should be private.

	/** Sets the lifetime of the summoned creature in ticks. */
	void setLifetime(int ticks);

	/**
	 * Returns the lifetime of the summoned creature in ticks. Allows primarily for duration multiplier support, but
	 * also for example the skeleton legion spell which lasts for 60 seconds instead of the usual 30. Syncing and saving
	 * is done automatically. As of Wizardry 2.1, despawning is handled in ISummonedCreature; see
	 * {@link ISummonedCreature#onDespawn()} for details.
	 */
	int getLifetime();

	/** Internal, do not use. Implementing classes should implement this to set their owner UUID field. */
	void setOwnerId(UUID uuid);

	/** Returns the UUID of the owner of this summoned creature, or null if it does not have an owner.
	 * Implementing classes should implement this to return their owner UUID field. */
	@Nullable
	@Override
	UUID getOwnerId(); // Only overridden because I wanted to add javadoc!

	@Nullable
	@Override
	default Entity getOwner(){
		return getCaster(); // Delegate to getCaster
	}

	/**
	 * Returns the EntityLivingBase that summoned this creature, or null if it no longer exists. Cases where the entity
	 * may no longer exist are: entity died or was deleted, mob despawned, player logged out, entity teleported to
	 * another dimension, or this creature simply had no caster in the first place.
	 */
	@Nullable
	default EntityLivingBase getCaster(){ // Kept despite the above method because it returns an EntityLivingBase

		if(this instanceof Entity){ // Bit of a cheat but it saves having yet another method just to get the world

			Entity entity = EntityUtils.getEntityByUUID(((Entity)this).world, getOwnerId());

			if(entity != null && !(entity instanceof EntityLivingBase)){ // Should never happen
				Wizardry.logger.warn("{} has a non-living owner!", this);
				return null;
			}

			return (EntityLivingBase)entity;

		}else{
			Wizardry.logger.warn("{} implements ISummonedCreature but is not an SoundLoopSpellEntity!", this.getClass());
			return null;
		}
	}

	/**
	 * Sets the EntityLivingBase that summoned this creature.
	 */
	default void setCaster(@Nullable EntityLivingBase caster){
		setOwnerId(caster == null ? null : caster.getUniqueID());
	}

	// Miscellaneous

	/**
	 * Called by the server when constructing the spawn packet. Data should be added to the provided stream.
	 * <b>Implementors must call super when overriding.</b>
	 *
	 * @param buffer The packet data stream
	 */
	@Override
	default void writeSpawnData(ByteBuf buffer){
		buffer.writeInt(getCaster() != null ? getCaster().getEntityId() : -1);
		buffer.writeInt(getLifetime());
	}

	/**
	 * Called by the client when it receives a Entity spawn packet. Data should be read out of the stream in the same
	 * way as it was written. <b>Implementors must call super when overriding.</b>
	 *
	 * @param buffer The packet data stream
	 */
	@Override
	default void readSpawnData(ByteBuf buffer){
		int id = buffer.readInt();
		// We're on the client side here, so we can safely use Minecraft.getMinecraft().world via proxies.
		if(id > -1){
			Entity entity = Wizardry.proxy.getTheWorld().getEntityByID(id);
			if(entity instanceof EntityLivingBase) setCaster((EntityLivingBase)entity);
			else Wizardry.logger.warn("Received a spawn packet for entity {}, but no living entity matched the supplied ID", this);
		}
		setLifetime(buffer.readInt());
	}

	/**
	 * Determines whether the given target is valid. Used by the default target selector (see
	 * {@link ISummonedCreature#getTargetSelector()}) and revenge targeting checks. This method is responsible for the
	 * ally designation system, default classes that may be targeted and the config whitelist/blacklist.
	 * Implementors may override this if they want to do something different or add their own checks.
	 * @see AllyDesignationSystem#isValidTarget(Entity, Entity)
	 */
	default boolean isValidTarget(Entity target){
		// If the target is valid based on the ADS...
		if(AllyDesignationSystem.isValidTarget(this.getCaster(), target)){

			// ...and is a player, they can be attacked, since players can't be in the whitelist or the
			// blacklist...
			if(target instanceof EntityPlayer){
				// ...unless the creature was summoned by a good wizard who the player has not angered.
				if(getCaster() instanceof EntityWizard){
					if(getCaster().getRevengeTarget() != target
							&& ((EntityWizard)getCaster()).getAttackTarget() != target) {
						return false;
					}
				}

				return true;
			}

			// ...and is a mob, a summoned creature, a wizard...
			if((target instanceof IMob || target instanceof ISummonedCreature
					|| (target instanceof EntityWizard && !(getCaster() instanceof EntityWizard))
					// ...or something that's attacking the owner...
					|| (target instanceof EntityLiving && ((EntityLiving)target).getAttackTarget() == getCaster())
					// ...or in the whitelist...
					|| Arrays.asList(Wizardry.settings.summonedCreatureTargetsWhitelist)
					.contains(EntityList.getKey(target.getClass())))
					// ...and isn't in the blacklist...
					&& !Arrays.asList(Wizardry.settings.summonedCreatureTargetsBlacklist)
					.contains(EntityList.getKey(target.getClass()))){
				// ...it can be attacked.
				return true;
			}
		}

		return false;
	}

	/**
	 * Returns a entity selector to be passed into AI methods. Normally, this should not be overridden, but it is
	 * possible for implementors to override this in order to do something special when selecting a target.
	 */
	default Predicate<Entity> getTargetSelector(){
		return entity -> !entity.isInvisible() && (getCaster() == null ? entity instanceof EntityPlayer &&
				!((EntityPlayer)entity).isCreative() : isValidTarget(entity));
	}

	/**
	 * Called when this creature has existed for 1 tick, effectively when it has just been spawned. Normally used to add
	 * particles, sounds, etc.
	 */
	void onSpawn();

	/**
	 * Called when this summoned creature vanishes. Normally used to add particles, sounds, etc.
	 */
	void onDespawn();

	/** Whether this creature should spawn a subtle black swirl particle effect while alive. */
	boolean hasParticleEffect();

	/** Returns whether this creature has an animation when appearing and disappearing. */
	default boolean hasAnimation(){
		return true;
	}

	/** Returns the colour of this creature's appear/disappear animation. */
	default int getAnimationColour(float animationProgress){
		return 0x000000;
	}

	/**
	 * Called from the event handler after the damage change is applied. Does nothing by default, but can be overridden
	 * to do something when a successful attack is made. This was added because the event-based damage source system can
	 * cause parts of attackEntityAsMob not to fire, since attackEntityFrom is intercepted and canceled.
	 * <p></p>
	 * Usage examples: {@link EntitySilverfishMinion} uses this to summon more silverfish if the target is killed,
	 * {@link EntitySkeletonMinion} and {@link EntitySpiderMinion} use this to add potion effects to the target.
	 */
	default void onSuccessfulAttack(EntityLivingBase target){
	}

	// Delegates

	/**
	 * Implementors should call this from writeEntityToNBT. Can be overridden as long as super is called, but there's
	 * very little point in doing that since anything extra could just be added to writeEntityToNBT anyway.
	 */
	default void writeNBTDelegate(NBTTagCompound tagcompound){
		if(this.getCaster() != null){
			tagcompound.setUniqueId("casterUUID", this.getCaster().getUniqueID());
		}
		tagcompound.setInteger("lifetime", getLifetime());
	}

	/**
	 * Implementors should call this from readEntityFromNBT. Can be overridden as long as super is called, but there's
	 * very little point in doing that since anything extra could just be added to readEntityFromNBT anyway.
	 */
	default void readNBTDelegate(NBTTagCompound tagcompound){
		this.setOwnerId(tagcompound.getUniqueId("casterUUID"));
		this.setLifetime(tagcompound.getInteger("lifetime"));
	}

	/**
	 * Implementors should call this from setRevengeTarget, and call super.setRevengeTarget if and only if this method
	 * returns <b>true</b>.
	 */
	default boolean shouldRevengeTarget(EntityLivingBase entity){
		// Allows the config to prevent minions from revenge-targeting their owners (or anything else, for that matter)
		return Wizardry.settings.minionRevengeTargeting || isValidTarget(entity);
	}

	/**
	 * Implementors should call this from onUpdate. Can be overridden as long as super is called, but there's very
	 * little point in doing that since anything extra could just be added to onUpdate anyway.
	 */
	default void updateDelegate(){

		if(!(this instanceof Entity))
			throw new ClassCastException("Implementations of ISummonedCreature must extend SoundLoopSpellEntity!");

		Entity thisEntity = ((Entity)this);

		if(thisEntity.ticksExisted == 1){
			this.onSpawn();
		}

		// For some reason Minecraft reads the entity from NBT just after the entity is created, so setting -1 as a
		// default lifetime doesn't work. The easiest way around this is to use 0 - nobody's going to need it!
		if(thisEntity.ticksExisted > this.getLifetime() && this.getLifetime() > 0){
			this.onDespawn();
			thisEntity.setDead();
		}

		if(this.hasParticleEffect() && thisEntity.world.isRemote && thisEntity.world.rand.nextInt(8) == 0)
			ParticleBuilder.create(Type.DARK_MAGIC)
			.pos(thisEntity.posX, thisEntity.posY + thisEntity.world.rand.nextDouble() * 1.5, thisEntity.posZ)
			.clr(0.1f, 0.0f, 0.0f)
			.spawn(thisEntity.world);

	}

	/**
	 * Implementors should call this from processInteract, and call super.processInteract if and only if this method
	 * returns <b>false</b>.
	 */
	default boolean interactDelegate(EntityPlayer player, EnumHand hand){

		ItemStack stack = player.getHeldItem(hand);

		WizardData data = WizardData.get(player);
		// Selects one of the player's minions.
		if(player.isSneaking() && stack.getItem() instanceof ISpellCastingItem){

			if(!player.world.isRemote && data != null && this.getCaster() == player){

				if(data.selectedMinion != null && data.selectedMinion.get() == this){
					// Deselects the selected minion if right-clicked again
					data.selectedMinion = null;
				}else{
					// Selects this minion
					data.selectedMinion = new WeakReference<>(this);
				}
				data.sync();
			}
			return true;
		}

		return false;
	}

	// Damage system

	@SubscribeEvent(priority = EventPriority.HIGHEST) // Needs to be first because we're replacing damage entirely
	static void onLivingAttackEvent(LivingAttackEvent event){

		// Rather than bother overriding entire attack methods in ISummonedCreature implementations, it's easier (and
		// more robust) to use LivingAttackEvent to modify the damage source.
		if(event.getSource().getTrueSource() instanceof ISummonedCreature){

			EntityLivingBase summoner = ((ISummonedCreature)event.getSource().getTrueSource()).getCaster();

			if(summoner != null){

				event.setCanceled(true);
				DamageSource newSource = event.getSource();
				// Copies over the original DamageType if appropriate.
				DamageType type = event.getSource() instanceof IElementalDamage
						? ((IElementalDamage)event.getSource()).getType()
						: DamageType.MAGIC;
				// Copies over the original isRetaliatory flag if appropriate.
				boolean isRetaliatory = event.getSource() instanceof IElementalDamage
						&& ((IElementalDamage)event.getSource()).isRetaliatory();

				// All summoned creatures are classified as magic, so it makes sense to do it this way.
				if(event.getSource() instanceof EntityDamageSourceIndirect){
					newSource = new IndirectMinionDamage(event.getSource().damageType,
							event.getSource().getImmediateSource(), event.getSource().getTrueSource(), summoner, type,
							isRetaliatory);
				}else if(event.getSource() instanceof EntityDamageSource){
					// Name is copied over so it uses the appropriate vanilla death message
					newSource = new MinionDamage(event.getSource().damageType, event.getSource().getTrueSource(), summoner,
							type, isRetaliatory);
				}

				// Copy over any relevant 'attributes' the original DamageSource might have had.
				if(event.getSource().isExplosion()) newSource.setExplosion();
				if(event.getSource().isFireDamage()) newSource.setFireDamage();
				if(event.getSource().isProjectile()) newSource.setProjectile();

				// For some reason Minecraft calculates knockback relative to DamageSource#getTrueSource. In vanilla this
				// is unnoticeable, but it looks a bit weird with summoned creatures involved - so this fixes that.
				// Damage safety checker falls back to the original damage source, so it behaves as if the creature has
				// no summoner.
				if(DamageSafetyChecker.attackEntitySafely(event.getEntity(), newSource, event.getAmount(), event.getSource(), false)){
					// Uses event.getSource().getTrueSource() as this means the target is knocked back from the minion
					EntityUtils.applyStandardKnockback(event.getSource().getTrueSource(), event.getEntityLiving());
					((ISummonedCreature)event.getSource().getTrueSource()).onSuccessfulAttack(event.getEntityLiving());
					// If the target revenge-targeted the summoner, make it revenge-target the minion instead
					// (if it didn't revenge-target, do nothing)
					if(event.getEntityLiving().getRevengeTarget() == summoner
							&& event.getSource().getTrueSource() instanceof EntityLivingBase){
						event.getEntityLiving().setRevengeTarget((EntityLivingBase)event.getSource().getTrueSource());
					}
				}

			}
		}
	}

}

package electroblob.wizardry.misc;

import electroblob.wizardry.util.InventoryUtils;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTUtil;
import net.minecraft.network.PacketBuffer;
import net.minecraft.village.MerchantRecipe;
import net.minecraft.village.MerchantRecipeList;
import net.minecraftforge.oredict.OreDictionary;

/** Custom version of {@link MerchantRecipeList} which allows wildcard recipes (i.e. trades which accept items with any
 * damage value). Function is otherwise identical. For some reason this feature was removed in 1.11.
 * @author Electroblob
 * @since Wizardry 4.1 */
@SuppressWarnings("serial")
public class WildcardTradeList extends MerchantRecipeList {

	private int currentIndex;

	public WildcardTradeList(){
		super();
	}

	public WildcardTradeList(NBTTagCompound tag){
		super(tag);
	}

	/** Returns the current recipe  */
	public MerchantRecipe getCurrentRecipe(){
		return get(currentIndex); // Allows events to access the selected recipe without reflection
	}

	@Override
    public MerchantRecipe canRecipeBeUsed(ItemStack offer1, ItemStack offer2, int index){

		currentIndex = index; // Update the index

        if(index > 0 && index < this.size()){

            MerchantRecipe merchantrecipe1 = this.get(index);
            return !this.areItemStacksExactlyEqual(offer1, merchantrecipe1.getItemToBuy()) || (!offer2.isEmpty() || merchantrecipe1.hasSecondItemToBuy()) && (!merchantrecipe1.hasSecondItemToBuy() || !this.areItemStacksExactlyEqual(offer2, merchantrecipe1.getSecondItemToBuy())) || offer1.getCount() < merchantrecipe1.getItemToBuy().getCount() || merchantrecipe1.hasSecondItemToBuy() && offer2.getCount() < merchantrecipe1.getSecondItemToBuy().getCount() ? null : merchantrecipe1;

        }else{

            for(int i = 0; i < this.size(); ++i){

                MerchantRecipe merchantrecipe = this.get(i);

                if (this.areItemStacksExactlyEqual(offer1, merchantrecipe.getItemToBuy()) && offer1.getCount() >= merchantrecipe.getItemToBuy().getCount() && (!merchantrecipe.hasSecondItemToBuy() && offer2.isEmpty() || merchantrecipe.hasSecondItemToBuy() && this.areItemStacksExactlyEqual(offer2, merchantrecipe.getSecondItemToBuy()) && offer2.getCount() >= merchantrecipe.getSecondItemToBuy().getCount())){
                    return merchantrecipe;
                }
            }

            return null;
        }
    }

    private boolean areItemStacksExactlyEqual(ItemStack stack1, ItemStack stack2){
    	// Added to allow wildcards
    	if((stack1.getItemDamage() == OreDictionary.WILDCARD_VALUE || stack2.getItemDamage() == OreDictionary.WILDCARD_VALUE)
    			// Can't use ItemStack.areItemsEqualIgnoreDurability because that only works for items with durability, not subtypes.
    			&& stack1.getItem() == stack2.getItem()) return true;

        return ItemStack.areItemsEqual(stack1, stack2) && (!stack2.hasTagCompound() || stack1.hasTagCompound() && NBTUtil.areNBTEquals(stack2.getTagCompound(), stack1.getTagCompound(), false));
    }

	@Override
	public void writeToBuf(PacketBuffer buffer){

		buffer.writeByte((byte)(this.size() & 255));

		// Trick the client into thinking this is a normal item
		for(MerchantRecipe merchantrecipe : this){

			ItemStack itemToBuy = merchantrecipe.getItemToBuy();
			if(itemToBuy.getMetadata() == OreDictionary.WILDCARD_VALUE) itemToBuy = InventoryUtils.copyWithMeta(itemToBuy, 0);
			buffer.writeItemStack(itemToBuy);

			ItemStack itemToSell = merchantrecipe.getItemToSell();
			if(itemToSell.getMetadata() == OreDictionary.WILDCARD_VALUE) itemToSell = InventoryUtils.copyWithMeta(itemToSell, 0);
			buffer.writeItemStack(itemToSell);

			ItemStack secondItemToBuy = merchantrecipe.getSecondItemToBuy();
			buffer.writeBoolean(!secondItemToBuy.isEmpty());

			if(!secondItemToBuy.isEmpty()){
				if(secondItemToBuy.getMetadata() == OreDictionary.WILDCARD_VALUE) secondItemToBuy = InventoryUtils.copyWithMeta(secondItemToBuy, 0);
				buffer.writeItemStack(secondItemToBuy);
			}

			buffer.writeBoolean(merchantrecipe.isRecipeDisabled());
			buffer.writeInt(merchantrecipe.getToolUses());
			buffer.writeInt(merchantrecipe.getMaxTradeUses());
		}
	}

}

package electroblob.wizardry.tileentity;

import electroblob.wizardry.Wizardry;
import electroblob.wizardry.block.BlockBookshelf;
import electroblob.wizardry.inventory.ContainerBookshelf;
import electroblob.wizardry.util.NBTExtras;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.entity.player.InventoryPlayer;
import net.minecraft.inventory.Container;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.nbt.NBTTagList;
import net.minecraft.network.NetworkManager;
import net.minecraft.network.play.server.SPacketUpdateTileEntity;
import net.minecraft.tileentity.TileEntity;
import net.minecraft.tileentity.TileEntityLockableLoot;
import net.minecraft.util.ITickable;
import net.minecraft.util.NonNullList;
import net.minecraft.util.text.ITextComponent;
import net.minecraft.util.text.TextComponentString;
import net.minecraft.util.text.TextComponentTranslation;
import net.minecraftforge.common.util.Constants.NBT;

import javax.annotation.Nullable;

public class TileEntityBookshelf extends TileEntityLockableLoot implements ITickable {

	/** NBT key for the boolean flag specifying if this bookshelf was generated naturally as part of a structure or not.
	 * This flag is set via {@link TileEntityBookshelf#markAsNatural(NBTTagCompound)}. */
	private static final String NATURAL_NBT_KEY = "NaturallyGenerated";
	/** When a non-spectating player comes within this distance of a naturally-generated bookshelf, it will automatically
	 * generate its loot if a loot table was set. This means the bookshelves do not incorrectly appear empty before a
	 * player looks inside. */ // Kind of a trade-off between not seeing them appear and not triggering from miles away
	private static final int LOOT_GEN_DISTANCE = 32; // Nobody is likely to be looking from more than 32 blocks away

	/** The inventory of the bookshelf. */
	private NonNullList<ItemStack> inventory;

	/** Whether this bookshelf was generated naturally as part of a structure. This determines whether the loot is
	 * automatically generated (and synced) when a non-spectating player comes within {@value LOOT_GEN_DISTANCE} blocks,
	 * so the bookshelf doesn't look empty until opened (loot is generated with that player in the context). */
	private boolean natural;
	private boolean doNotSync;

	public TileEntityBookshelf(){
		inventory = NonNullList.withSize(BlockBookshelf.SLOT_COUNT, ItemStack.EMPTY);
		// Prevent sync() happening when loading from NBT or weirdness ensues when loading a world
		// Normally I'd pass this as a flag to setInventorySlotContents but we can't change the method signature
		this.doNotSync = true;
	}

	/** Called to manually sync the tile entity with clients. */
	public void sync(){
		if(!this.doNotSync)
			this.world.markAndNotifyBlock(pos, null, world.getBlockState(pos), world.getBlockState(pos), 3);
	}

	@Override
	public void update(){

		this.doNotSync = false;

		// When a player gets near, generate the books so they can actually see them (if it was generated naturally)
		if(lootTable != null && natural){
			EntityPlayer player = world.getClosestPlayer(pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5,
					LOOT_GEN_DISTANCE, false);
			if(player != null){
				natural = false; // It's a normal bookshelf now (unlikely to matter but you never know)
				fillWithLoot(player);
				sync();
			}
		}
	}

	@Override
	public int getSizeInventory(){
		return inventory.size();
	}

	// Still better to override these three because then we can sync only when necessary

	@Override
	public ItemStack decrStackSize(int slot, int amount){

		this.fillWithLoot(null);

		ItemStack stack = getStackInSlot(slot);

		if(!stack.isEmpty()){
			if(stack.getCount() <= amount){
				setInventorySlotContents(slot, ItemStack.EMPTY);
			}else{
				stack = stack.splitStack(amount);
				if(stack.getCount() == 0){
					setInventorySlotContents(slot, ItemStack.EMPTY);
				}
			}
			this.markDirty();
		}

		return stack;
	}

	@Override
	public ItemStack removeStackFromSlot(int slot){

		this.fillWithLoot(null);

		ItemStack stack = getStackInSlot(slot);

		if(!stack.isEmpty()){
			setInventorySlotContents(slot, ItemStack.EMPTY);
		}

		return stack;
	}

	@Override
	public void setInventorySlotContents(int slot, ItemStack stack){
		this.fillWithLoot(null);
		boolean wasEmpty = inventory.get(slot).isEmpty();
		super.setInventorySlotContents(slot, stack);
		// This must be done in the tile entity because containers only exist for player interaction, not hoppers etc.
		if(wasEmpty != stack.isEmpty()) this.sync();
		this.markDirty();
	}

	/** Sets the {@value NATURAL_NBT_KEY} flag to true in the given NBT tag compound, <b>if</b> the compound belongs to
	 * a bookshelf tile entity (more specifically, if it has an "id" tag matching the bookshelf TE's registry name). */
	public static void markAsNatural(NBTTagCompound nbt){
		if(nbt != null && nbt.getString("id").equals(TileEntity.getKey(TileEntityBookshelf.class).toString())){
			nbt.setBoolean(NATURAL_NBT_KEY, true);
		}
	}

	@Override
	public void fillWithLoot(@Nullable EntityPlayer player){
		if(world != null && world.getLootTableManager() != null) super.fillWithLoot(player); // IntelliJ is wrong, it can be null
	}

	@Override
	public String getName(){
		return "container." + Wizardry.MODID + ":bookshelf";
	}

	@Override
	public boolean hasCustomName(){
		return false;
	}

	@Override
	public ITextComponent getDisplayName(){
		return this.hasCustomName() ? new TextComponentString(this.getName()) : new TextComponentTranslation(this.getName());
	}

	@Override
	public int getInventoryStackLimit(){
		return 64;
	}

	@Override
	public boolean isUsableByPlayer(EntityPlayer player){
		return world.getTileEntity(pos) == this && player.getDistanceSqToCenter(pos) < 64;
	}

	@Override
	public void openInventory(EntityPlayer player){

	}

	@Override
	public void closeInventory(EntityPlayer player){

	}

	@Override
	public boolean isItemValidForSlot(int slotNumber, ItemStack stack){
		return stack.isEmpty() || ContainerBookshelf.isBook(stack);
	}

	@Override
	public void readFromNBT(NBTTagCompound nbt){

		super.readFromNBT(nbt);

		natural = nbt.getBoolean(NATURAL_NBT_KEY);

		if(!this.checkLootAndRead(nbt)){

			NBTTagList tagList = nbt.getTagList("Inventory", NBT.TAG_COMPOUND);

			for(int i = 0; i < tagList.tagCount(); i++){
				NBTTagCompound tag = tagList.getCompoundTagAt(i);
				byte slot = tag.getByte("Slot");
				if(slot >= 0 && slot < getSizeInventory()){
					setInventorySlotContents(slot, new ItemStack(tag));
				}
			}
		}

		if(nbt.hasKey("CustomName", NBT.TAG_STRING)) this.customName = nbt.getString("CustomName");
	}

	@Override
	public NBTTagCompound writeToNBT(NBTTagCompound nbt){

		super.writeToNBT(nbt);

		// Need to save this in case the block was generated but no players came near enough to trigger loot gen
		nbt.setBoolean(NATURAL_NBT_KEY, natural);

		if(!this.checkLootAndWrite(nbt)){

			NBTTagList itemList = new NBTTagList();

			for(int i = 0; i < getSizeInventory(); i++){
				ItemStack stack = getStackInSlot(i);
				NBTTagCompound tag = new NBTTagCompound();
				tag.setByte("Slot", (byte)i);
				stack.writeToNBT(tag);
				itemList.appendTag(tag);
			}

			NBTExtras.storeTagSafely(nbt, "Inventory", itemList);
		}

		if(this.hasCustomName()) nbt.setString("CustomName", this.customName);

		return nbt;
	}

	@Override
	public final NBTTagCompound getUpdateTag(){
		return this.writeToNBT(new NBTTagCompound());
	}

	@Override
	public SPacketUpdateTileEntity getUpdatePacket(){
		return new SPacketUpdateTileEntity(pos, 0, this.getUpdateTag());
	}

	@Override
	public void onDataPacket(NetworkManager net, SPacketUpdateTileEntity pkt){
		readFromNBT(pkt.getNbtCompound());
		Wizardry.proxy.notifyBookshelfChange(world, pos);
	}

	// What are all these for?

	@Override
	public int getField(int id){
		return 0;
	}

	@Override
	public void setField(int id, int value){

	}

	@Override
	public int getFieldCount(){
		return 0;
	}

	@Override
	public void clear(){
		for(int i = 0; i < getSizeInventory(); i++){
			setInventorySlotContents(i, ItemStack.EMPTY);
		}
	}

	@Override
	public boolean isEmpty(){
		for(int i = 0; i < getSizeInventory(); i++){
			if(!getStackInSlot(i).isEmpty()){
				return false;
			}
		}
		return true;
	}

	@Override
	protected NonNullList<ItemStack> getItems(){
		return inventory;
	}

	@Override
	public Container createContainer(InventoryPlayer playerInventory, EntityPlayer player){
		this.fillWithLoot(player);
		return new ContainerBookshelf(playerInventory, this);
	}

	@Override
	public String getGuiID(){
		return Wizardry.MODID + ":bookshelf";
	}

}

package electroblob.wizardry.util;

import com.google.common.collect.Sets;
import electroblob.wizardry.event.SpellCastEvent;
import io.netty.buffer.ByteBuf;
import net.minecraft.item.Item;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraftforge.fml.common.network.ByteBufUtils;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Map.Entry;

/**
 * <i>"{@code SpellModifiers} - modify all the things!"</i>
 * <p></p>
 * Object that wraps any number of spell modifiers into one, allowing for expandability within the Spell#cast methods.
 * This class is essentially a glorified {@link Map} which can be written to and read from a {@link ByteBuf}.
 * <p></p>
 * Most external interaction with SpellModifiers objects will be in {@link SpellCastEvent.Pre}, where you can add
 * additional modifiers to them if desired for use with your own spells, or modify the existing ones. If you have added
 * a wand upgrade, this is <b>not</b> done automatically for you; you will have to do it yourself (for the simple reason
 * that not all wand upgrades affect spells). SpellModifiers objects are <i>mutable</i>, so you can simply change the
 * values they contain to modify the spell.
 * <p></p>
 * To use a SpellModifiers object within the <code>Spell.cast</code> methods, simply retrieve the desired modifier
 * using {@link SpellModifiers#get(Item)} for wand upgrades, or {@link SpellModifiers#get(String)} if the modifier is
 * not from a wand upgrade.
 * 
 * @author Electroblob
 * @since Wizardry 1.2
 * @see WandHelper
 */
// I have made the decision that the USERS of this class must decide whether the modifiers need syncing or not, on a
// case-by-case basis. Why? Because assigning keys to either sync or not sync would be unnecessarily restrictive, and
// would mean they have to be registered, and part of the point of SpellModifiers is that they can be added to on the
// fly.
public final class SpellModifiers {

	/** Constant string identifier for the potency modifier. */
	public static final String POTENCY = "potency";
	/** Constant string identifier for the mana cost modifier. */
	public static final String COST = "cost";
	/** Constant string identifier for the wand charge-up modifier. */
	public static final String CHARGEUP = "chargeup";
	/** Constant string identifier for the wand progression modifier. */
	public static final String PROGRESSION = "progression";

	private final Map<String, Float> multiplierMap;
	private final Map<String, Float> syncedMultiplierMap;

	/**
	 * Creates an empty SpellModifiers object. All calls to <code>get(...)</code> on an empty SpellModifiers object will
	 * return a value of 1.
	 */
	public SpellModifiers(){
		multiplierMap = new HashMap<>();
		syncedMultiplierMap = new HashMap<>();
	}

	private SpellModifiers(Map<String, Float> multiplierMap, Map<String, Float> syncedMultiplierMap){
		this.multiplierMap = multiplierMap;
		this.syncedMultiplierMap = syncedMultiplierMap;
	}

	/** Returns a deep copy (with copies of the underlying maps) of this {@code SpellModifiers} object. */
	public SpellModifiers copy(){
		return new SpellModifiers(new HashMap<>(this.multiplierMap), new HashMap<>(this.syncedMultiplierMap));
	}

	/**
	 * Combines the given SpellModifiers object with this one. More specifically: for each modifier, multiplies the
	 * values from both objects together and sets it to sync if either object does so. This method changes the object
	 * it is called on but not the one given as a parameter; apart from this it does not matter which way round the two
	 * objects are.
	 * @param modifiers The SpellModifiers object to combine with this one; will not be modified by this method.
	 * @return The SpellModifiers object, allowing this method to be chained onto the constructor.
	 */
	public SpellModifiers combine(SpellModifiers modifiers){
		for(String key : Sets.union(this.multiplierMap.keySet(), modifiers.multiplierMap.keySet())){
			float newValue = this.get(key) * modifiers.get(key);
			// Also need to update the synced map if the modifier is synced in either object
			boolean sync = this.syncedMultiplierMap.containsKey(key) || modifiers.syncedMultiplierMap.containsKey(key);
			this.set(key, newValue, sync);
		}
		return this;
	}

	/**
	 * Adds the given multiplier to this SpellModifiers object, using the string identifier that the given wand upgrade
	 * item was registered with.
	 * 
	 * @throws IllegalArgumentException if the given item is not a registered special wand upgrade.
	 * @param upgrade The upgrade item the multiplier corresponds to.
	 * @param multiplier The multiplier value, with 1 being default. Usage of modifiers is up to individual spells to
	 *        implement.
	 * @param needsSyncing Whether this multiplier should be synchronised with the client via packets. <i>Only set this
	 *        to true if particles will be spawned which need to know the value of the multiplier.</i>
	 * @return The SpellModifiers object, allowing this method to be chained onto the constructor.
	 */
	public SpellModifiers set(Item upgrade, float multiplier, boolean needsSyncing){
		this.set(WandHelper.getIdentifier(upgrade), multiplier, needsSyncing);
		return this;
	}

	/**
	 * Adds the given multiplier to this SpellModifiers object, using the given string key. In most cases, the
	 * multiplier will correspond to a wand upgrade, in which case use {@link SpellModifiers#set(Item, float, boolean)}
	 * instead.
	 * 
	 * @param key The key used to identify the multiplier.
	 * @param multiplier The multiplier value, with 1 being default. Usage of modifiers is up to individual spells to
	 *        implement.
	 * @param needsSyncing Whether this multiplier should be synchronised with the client via packets. <i>Only set this
	 *        to true if particles will be spawned which depend on the multiplier.</i>
	 * @return The SpellModifiers object, allowing this method to be chained onto the constructor.
	 */
	public SpellModifiers set(String key, float multiplier, boolean needsSyncing){
		multiplierMap.put(key, multiplier);
		if(needsSyncing) syncedMultiplierMap.put(key, multiplier);
		return this;
	}

	/**
	 * Returns the multiplier corresponding to the given wand upgrade item, or 1 if no multiplier was stored.
	 * 
	 * @throws IllegalArgumentException if the given item is not a registered special wand upgrade.
	 */
	public float get(Item upgrade){
		return get(WandHelper.getIdentifier(upgrade));
	}

	/**
	 * Returns the multiplier corresponding to the given string key, or 1 if no multiplier was stored. In most cases,
	 * the multiplier will correspond to a wand upgrade, in which case use {@link SpellModifiers#get(Item)} instead.
	 */
	public float get(String key){
		Float value = multiplierMap.get(key);
		// Must check for null before unboxing, and if it is null, return the default 1.
		return value == null ? 1 : value;
	}

	// Not sure this really makes sense with the current system, it may just be better to keep it how it is
//	/**
//	 * Returns the <i>level</i> of upgrade (i.e. number of upgrades or wand tier) that would be required to
//	 * generate a modifier with the given key. <i>This does not necessarily mean that was how this modifier was
//	 * applied; and the returned value may not be a whole number if commands were involved.</i>
//	 */
//	public float level(String key){
//		return 0;
//	}

	/**
	 * Returns an amplified version of the multiplier corresponding to the given string key. An <i>amplified</i>
	 * modifier is the original modifier <i>scaled about 1</i> - for example, amplifying by 2 would produce the
	 * following results:<br>
	 * 1.3 -> 1.6<br>
	 * 2 -> 3<br>
	 * 0.7 -> 0.4<br>
	 * 1 -> 1<br>
	 * (In other words, the modifier is decreased by 1, multiplied by the scalar and then increased by 1 again.)<br>
	 * <b>N.B. This does not change the stored modifier.</b>
	 */
	public float amplified(String key, float scalar){
		return (get(key) - 1) * scalar + 1;
	}

	/**
	 * Returns an unmodifiable map of the modifiers stored in this SpellModifiers object. Useful for iterating through
	 * the modifiers.
	 */
	public Map<String, Float> getModifiers(){
		return Collections.unmodifiableMap(this.multiplierMap);
	}

	/** Removes all modifiers from this SpellModifiers object, effectively resetting them all to 1. */
	public void reset(){
		this.multiplierMap.clear();
		this.syncedMultiplierMap.clear();
	}

	/** Reads this SpellModifiers object from the given ByteBuf. */
	public void read(ByteBuf buf){
		int entryCount = buf.readInt();
		for(int i = 0; i < entryCount; i++){
			this.set(ByteBufUtils.readUTF8String(buf), buf.readFloat(), false);
		}
	}

	/** Writes this SpellModifiers object to the given ByteBuf so it can be sent via packets. */
	public void write(ByteBuf buf){
		buf.writeInt(syncedMultiplierMap.size());
		for(Entry<String, Float> entry : syncedMultiplierMap.entrySet()){
			ByteBufUtils.writeUTF8String(buf, entry.getKey());
			buf.writeFloat(entry.getValue());
		}
	}

	// These two don't use the Map <-> NBT methods in WizardryUtilities because it's better to use the strings as keys
	// themselves rather than storing them separately.

	/**
	 * Creates a new SpellModifiers object from the given NBTTagCompound. The NBTTagCompound should have 1 or more float
	 * tags, which will be stored as modifiers under the same name as the tag. For example, the following NBT tag (in
	 * command syntax) represents a SpellModifiers object with a damage modifier of 1.5 and a range modifier of 2:
	 * <p></p>
	 * <code>{damage:1.5, range:2}</code>
	 * <p></p>
	 * Note that needsSyncing is set to true for all returned modifiers.
	 */
	public static SpellModifiers fromNBT(NBTTagCompound nbt){
		SpellModifiers modifiers = new SpellModifiers();
		for(String key : nbt.getKeySet()){
			modifiers.set(key, nbt.getFloat(key), true);
		}
		return modifiers;
	}

	/**
	 * Creates a new NBTTagCompound for this SpellModifiers object. The NBTTagCompound will have a float tags for each
	 * modifier, which will be stored using the modifier names as keys. For example, the following NBT tag (in
	 * command syntax) represents a SpellModifiers object with a damage modifier of 1.5 and a range modifier of 2:
	 * <p></p>
	 * <code>{damage:1.5, range:2}</code>
	 * <p></p>
	 * Note that information about syncing of modifiers is discarded.
	 */
	public NBTTagCompound toNBT(){
		NBTTagCompound nbt = new NBTTagCompound();
		for(Entry<String, Float> entry : multiplierMap.entrySet()){
			nbt.setFloat(entry.getKey(), entry.getValue());
		}
		return nbt;
	}

}
